const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Brazil geometry
  var brazil = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Brazil'));

  // Get MODIS Active Fire detections
  var fires2007 = ee.FeatureCollection('MODIS/006/MCD14ML')
    .filterBounds(brazil)
    .filter(ee.Filter.date('2007-01-01', '2007-12-31'));

  var fires2019 = ee.FeatureCollection('MODIS/006/MCD14ML')
    .filterBounds(brazil)
    .filter(ee.Filter.date('2019-01-01', '2019-12-31'));

  // Check if collections are empty
  var count2007 = fires2007.size().getInfo();
  var count2019 = fires2019.size().getInfo();

  console.log(`2007 Fire Detections: ${count2007}`);
  console.log(`2019 Fire Detections: ${count2019}`);

  if (count2007 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Compare fire detections
  var fewerIn2019 = count2019 < count2007;

  if (fewerIn2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
